     6	/**
     7	 * Reads a scenario from stdin and writes the office's results to stdout.
     8	 *
     9	 * When the office objects to the scenario it writes nothing to stdout: the objection is
    10	 * described on stderr and reported as a failing exit status, so that a caller is never left
    11	 * reading results the office refused to give.
    12	 */
    13	public final class ClaimOfficeCli {
    14	
    15	    private static final int OBJECTION_STATUS = 1;
    16	
    17	    private ClaimOfficeCli() {
    18	    }
    19	
    20	    public static void main(String[] args) {
    21	        System.exit(run());
    22	    }
    23	
    24	    public static int run() {
    25	        String results;
    26	        try {
    27	            ScenarioJson correspondence = new ScenarioJson();
    28	            Scenario scenario = correspondence.readScenario(readStandardInput());
    29	            results = correspondence.writeResults(new ClaimOffice().run(scenario));
    30	        } catch (ClaimOfficeException objection) {
    31	            new PrintStream(System.err, true, StandardCharsets.UTF_8).println(objection.getMessage());
    32	            return OBJECTION_STATUS;
    33	        }
    34	        new PrintStream(System.out, true, StandardCharsets.UTF_8).println(results);
    35	        return 0;
    36	    }
    37	
    38	    private static String readStandardInput() {
    39	        try (InputStream in = System.in) {
    40	            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
    41	        } catch (IOException unreadable) {
    42	            throw new ClaimOfficeException("The scenario could not be read: " + unreadable.getMessage());
    43	        }
    44	    }
    45	}
