     7	
     8	/**
     9	 * Translates between the scenario document the office is sent and the office's own terms.
    10	 *
    11	 * This is the office's correspondence clerk: it reads a scenario written in JSON and writes
    12	 * the results back in the same form. No rule of the office lives here -- only the wording.
    13	 */
    14	public class ScenarioJson {
    15	
    16	    private final ObjectMapper mapper = new ObjectMapper();
    17	
    18	    public Scenario readScenario(String document) {
    19	        JsonNode root = readTree(document);
    20	        List<Step> steps = new ArrayList<>();
    21	        for (JsonNode step : root.path("steps")) {
    22	            steps.add(readStep(step));
    23	        }
    24	        return new Scenario(new Customer(root.path("customer").path("yearsWithMHPCO").asInt()), steps);
    25	    }
    26	
    27	    public String writeResults(List<StepResult> results) {
    28	        ObjectNode root = mapper.createObjectNode();
    29	        ArrayNode written = root.putArray("results");
    30	        for (StepResult result : results) {
    31	            written.add(writeResult(result));
    32	        }
    33	        return root.toString();
    34	    }
    35	
    36	    private JsonNode readTree(String document) {
    37	        try {
    38	            return mapper.readTree(document);
    39	        } catch (com.fasterxml.jackson.core.JsonProcessingException malformed) {
    40	            throw new ClaimOfficeException("The scenario could not be read: " + malformed.getOriginalMessage());
    41	        }
    42	    }
    43	
    44	    private Step readStep(JsonNode step) {
    45	        if ("claim".equals(step.path("op").asText())) {
    46	            return new ClaimStep(step.path("policy").asInt(), readIncident(step.path("incident")));
    47	        }
    48	        List<Item> items = new ArrayList<>();
    49	        for (JsonNode item : step.path("items")) {
    50	            items.add(readItem(item));
    51	        }
    52	        return new QuoteStep(items);
    53	    }
    54	
    55	    private Item readItem(JsonNode item) {
    56	        return new Item(item.path("type").asText(),
    57	                item.path("material").asText(null),
    58	                item.path("enchantment").asInt(),
    59	                item.path("cursed").asBoolean());
    60	    }
    61	
    62	    private Incident readIncident(JsonNode incident) {
    63	        List<Damage> damages = new ArrayList<>();
    64	        for (JsonNode damage : incident.path("damages")) {
    65	            damages.add(new Damage(damage.path("itemType").asText(), damage.path("amount").asInt()));
    66	        }
    67	        return new Incident(incident.path("cause").asText(), damages);
    68	    }
    69	
    70	    private ObjectNode writeResult(StepResult result) {
    71	        ObjectNode written = mapper.createObjectNode();
    72	        if (result instanceof QuoteResult quoteResult) {
    73	            written.put("premium", quoteResult.premium());
    74	        } else {
    75	            ClaimResult claimResult = (ClaimResult) result;
    76	            written.put("payout", claimResult.payout());
    77	            written.put("remainingCap", claimResult.remainingCap());
    78	        }
    79	        return written;
    80	    }
    81	}
