     1	/**
     2	 * What the office pays out for an incident, settled against the cover a policy has left.
     3	 *
     4	 * The office settles an incident one damaged item at a time, and the incident's payout is
     5	 * what those settlements come to. The deductible is withheld per damage event, which is why
     6	 * it belongs to the single settlement and not to the tally.
     7	 *
     8	 * Whether a reported damage is one the office will settle at all is not this tally's
     9	 * business: the cover is asked, and it either names the item that answers for the damage or
    10	 * objects to the report. This tally only settles the reports that survive that asking.
    11	 */
    12	public class PayoutCalculator {
    13	
    14	    private static final int DEDUCTIBLE = 100;
    15	
    16	    private final ReimbursementClauses reimbursementClauses = new ReimbursementClauses();
    17	
    18	    public int payoutFor(Incident incident, UnclaimedCover unclaimedCover) {
    19	        double payout = 0;
    20	        for (Damage damage : incident.damages()) {
    21	            payout += settlementFor(damage, unclaimedCover);
    22	        }
    23	        return OfficesFavour.onAmountPaidOut(payout);
    24	    }
    25	
    26	    /**
    27	     * What one damaged item is settled at: the damage the office reimburses under the
    28	     * clauses that cover it, less the deductible it withholds for every damage event.
    29	     */
    30	    private double settlementFor(Damage damage, UnclaimedCover unclaimedCover) {
    31	        return reimbursementClauses.reimbursedAmountFor(damage, unclaimedCover.claimAgainst(damage))
    32	                - DEDUCTIBLE;
    33	    }
    34	}

