     1	import java.util.Map;
     2	import java.util.Set;
     3	
     4	/**
     5	 * The MHPCO price list: what the office charges to insure a single item, and what it
     6	 * insures that item for.
     7	 *
     8	 * The office prices two kinds of item differently. Each main item has its own listing, a
     9	 * single entry stating both of its figures. Components -- runes, moonstones -- share one
    10	 * uniform listing, so a new component type joins the list without figures of its own.
    11	 *
    12	 * The list is also the office's statement of what it insures: a type the list does not
    13	 * name is a type the office does not cover, and asking about it is met with an objection.
    14	 * Membership and figures are one fact per type, which is why they are kept together in one
    15	 * entry -- taking on a new line of business is a single new listing.
    16	 */
    17	public class PriceList {
    18	
    19	    /**
    20	     * What the list says about one type of item: the two figures the office quotes from.
    21	     */
    22	    private record Listing(int basePremium, int insuranceValue) {
    23	    }
    24	
    25	    private static final Map<String, Listing> MAIN_ITEM_LISTINGS = Map.of(
    26	            "sword", new Listing(100, 1000),
    27	            "amulet", new Listing(60, 600),
    28	            "staff", new Listing(80, 800),
    29	            "potion", new Listing(40, 400));
    30	
    31	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
    32	
    33	    private static final Listing COMPONENT_LISTING = new Listing(25, 250);
    34	
    35	    public boolean isComponent(Item item) {
    36	        return COMPONENT_TYPES.contains(item.type());
    37	    }
    38	
    39	    public int basePremiumFor(Item item) {
    40	        return listingFor(item).basePremium();
    41	    }
    42	
    43	    public int insuranceValueOf(Item item) {
    44	        return listingFor(item).insuranceValue();
    45	    }
    46	
    47	    /**
    48	     * The office's one act of looking a type up: components are all covered by the uniform
    49	     * component listing, a main item by its own, and a type with no listing is not insured
    50	     * at all.
    51	     */
    52	    private Listing listingFor(Item item) {
    53	        if (isComponent(item)) {
    54	            return COMPONENT_LISTING;
    55	        }
    56	        Listing listing = MAIN_ITEM_LISTINGS.get(item.type());
    57	        if (listing == null) {
    58	            throw new ClaimOfficeException("The office does not insure items of type " + item.type());
    59	        }
    60	        return listing;
    61	    }
    62	}
