     1	/**
     2	 * A risk the MHPCO recognises on a single insured item, and the surcharge rate it carries.
     3	 *
     4	 * The office's risk catalogue: each entry names one hazard, says when an item carries it,
     5	 * and at what rate. Revising a threshold or a rate is a change to one entry; recognising
     6	 * a new hazard is a new entry.
     7	 */
     8	public enum RecognisedRisk {
     9	
    10	    CURSE(0.50) {
    11	        @Override
    12	        boolean isCarriedBy(Item item) {
    13	            return item.cursed();
    14	        }
    15	    },
    16	
    17	    HIGH_ENCHANTMENT(0.30) {
    18	        /** The enchantment level from which the office surcharges a premium for risk. */
    19	        private static final int SURCHARGED_ENCHANTMENT_LEVEL = 5;
    20	
    21	        @Override
    22	        boolean isCarriedBy(Item item) {
    23	            return item.enchantment() >= SURCHARGED_ENCHANTMENT_LEVEL;
    24	        }
    25	    };
    26	
    27	    private final double rate;
    28	
    29	    RecognisedRisk(double rate) {
    30	        this.rate = rate;
    31	    }
